constexpr const char * lava_frag = R"glsl(#version 130

// ArxModern lava.
//
// The engine draws lava as a flat polygon with its own texture (already in the scene) and
// used to modulate three scrolling copies of the "enviro" highlight texture on top of it.
// This pass replaces that overlay: the molten veins glow and pulse, the crust between them
// darkens, the surface slowly heaves (the base texture is read back through a wobble), and
// a second draw of the polygons raised above the pool (u_haze != 0) distorts what is seen
// through the hot air.
//
// Inputs from the engine: u_scene / u_depth = the scene as rendered so far (resolved copies),
// u_enviro = the original highlight texture (unit 0) with its three scrolling uv sets.

uniform sampler2D u_enviro;
uniform sampler2D u_scene;
uniform sampler2D u_depth;
uniform vec2 u_invSize;
uniform vec4 u_projection; // (proj[0][0], proj[1][1], Q, Q * near): view z = Q * near / (Q - z_ndc)
uniform vec3 u_cameraPos;
uniform float u_time;
uniform float u_strength; // 0..1, overall intensity of the effect
uniform int u_fogEnabled;
uniform vec2 u_fogRange;
uniform int u_haze;       // 1 = the raised cap (heat haze), 0 = the surface

in vec3 v_worldPos;
in float v_viewDepth;
in float v_interior;
in vec2 v_uv0;
in vec2 v_uv1;
in vec2 v_uv2;

out vec4 fragColor;

// Tunables (a mod can edit this file: F7 reloads it)
const vec3 GlowColor = vec3(1.0, 0.45, 0.08);   // colour of the molten veins
const vec3 HotColor = vec3(1.0, 0.85, 0.5);     // colour of the hottest spots
const float Glow = 1.1;                         // emissive strength
const float Pulse = 0.25;                       // slow breathing of the glow
const float Crust = 0.5;                        // how dark the cooled crust gets
const float Wobble = 0.0025;                    // screen-space heave of the surface texture
const float Haze = 0.012;                       // screen-space distortion of the heat haze
const float HazeSpeed = 1.7;

float linearDepth(float zBuffer) {
	float zNdc = zBuffer * 2.0 - 1.0;
	return u_projection.w / (u_projection.z - zNdc);
}

float sceneDepth(vec2 uv) {
	return linearDepth(texture(u_depth, uv).r);
}

// Screen colour at uv + offset, unless something nearer than this fragment stands there
vec3 sceneBehind(vec2 uv, vec2 offset, float surfaceZ) {
	vec2 uv2 = clamp(uv + offset, u_invSize, 1.0 - u_invSize);
	if(sceneDepth(uv2) < surfaceZ - 1.0) {
		uv2 = uv;
	}
	return texture(u_scene, uv2).rgb;
}

void main() {

	vec2 uv = gl_FragCoord.xy * u_invSize;
	float surfaceZ = linearDepth(gl_FragCoord.z);
	float fade = clamp(v_interior, 0.0, 1.0) * u_strength;

	// The three scrolling layers of the original effect, as a "heat" field
	vec3 l0 = texture(u_enviro, v_uv0).rgb;
	vec3 l1 = texture(u_enviro, v_uv1).rgb;
	vec3 l2 = texture(u_enviro, v_uv2).rgb;
	// The product of the layers is about 0.2 on average: the veins are its high end, the
	// cooled crust its low end
	float product = l0.r * l1.g * l2.b;
	float heat = smoothstep(0.17, 0.42, product);
	float crust = smoothstep(0.16, 0.05, product);
	float fine = l1.r * l2.g * 2.0;

	if(u_haze != 0) {
		// Heat haze: the scene seen through the rising hot air, wavering
		vec2 wave = vec2(sin(v_worldPos.x * 0.05 + u_time * HazeSpeed * 1.3 + fine * 6.0),
		                 cos(v_worldPos.z * 0.045 + u_time * HazeSpeed + heat * 5.0));
		vec2 offset = wave * Haze * fade * (0.4 + 0.6 * heat);
		// Perspective: distort less far away
		offset *= clamp(400.0 / max(surfaceZ, 1.0), 0.2, 1.0);
		fragColor = vec4(sceneBehind(uv, offset, surfaceZ), 1.0);
		return;
	}

	// The surface: the base texture through a slow heave
	vec2 wobble = vec2(sin(u_time * 0.7 + v_worldPos.z * 0.02), cos(u_time * 0.5 + v_worldPos.x * 0.02)) * Wobble * fade;
	vec3 base = sceneBehind(uv, wobble, surfaceZ);

	// Glowing veins where the layers coincide, pulsing; darker crust where they do not
	float pulse = 1.0 + Pulse * sin(u_time * 1.1 + product * 12.0);
	float hot = heat * heat;
	vec3 color = base * (1.0 - Crust * crust) * (1.0 + Glow * heat * pulse);
	color += mix(GlowColor, HotColor, hot) * (hot * Glow * 0.5 * pulse);

	// Fog dims the glow as it does the scene
	if(u_fogEnabled != 0) {
		float fog = clamp((u_fogRange.y - v_viewDepth) / (u_fogRange.y - u_fogRange.x), 0.0, 1.0);
		color = mix(base, color, fog);
	}

	fragColor = vec4(mix(base, color, u_strength), 1.0);
}
)glsl";

constexpr const char * lava_vert = R"glsl(#version 130

// ArxModern lava: the lava polygons of the level (world space), drawn after the scene with
// the scene colour and depth available to the fragment shader. Drawn twice: the surface, and
// a "cap" raised by u_raise above the pool through which the heat haze is seen.

uniform mat4 u_viewProj;
uniform mat4 u_view;
uniform float u_raise;

in vec4 a_position;
in vec4 a_color; // r = 1 inside the pool, 0 at its edge (see RenderLava)
in vec2 a_texcoord0;
in vec2 a_texcoord1;
in vec2 a_texcoord2;

out vec3 v_worldPos;
out float v_viewDepth;
out float v_interior;
out vec2 v_uv0;
out vec2 v_uv1;
out vec2 v_uv2;

void main() {
	vec3 pos = a_position.xyz - vec3(0.0, u_raise, 0.0);
	v_worldPos = pos;
	v_viewDepth = abs((u_view * vec4(pos, 1.0)).z);
	v_interior = a_color.r;
	v_uv0 = a_texcoord0;
	v_uv1 = a_texcoord1;
	v_uv2 = a_texcoord2;
	gl_Position = u_viewProj * vec4(pos, 1.0);
}
)glsl";

constexpr const char * legacy_frag = R"glsl(#version 130

// ArxModern "legacy" fragment shader: reproduces the fixed-function texture combiners
// (GL_COMBINE with GL_MODULATE / GL_REPLACE and RGB/alpha scale) and linear fog.
//
// Per stage, u_stageN = ivec2(colorOp, alphaOp) with the TextureStage::TextureOp values:
//   0 = disabled   : pass the previous stage through
//   1 = select     : texture
//   2 = modulate   : texture * previous
//   3 = modulate2x : texture * previous * 2
//   4 = modulate4x : texture * previous * 4
// A stage without a bound texture is reported as (0, 0).
//
// Per-pixel lighting, with the engine's own formula (scene/Light.cpp): Lambert term, constant
// up to fallstart, linear falloff to zero at fallend. u_lightPos = (xyz, fallstart),
// u_lightColor = (rgb, fallend), rgb premultiplied by intensity and the global light factor.
// - Level geometry (u_pixelLighting != 0): the vertex color carries the precomputed static
//   lighting and the first u_dynamicLightCount lights are added at half strength
//   (ApplyTileLights).
// - Entities (v_diffuse > 0): the vertex color carries the ambient term and all lights are
//   added, scaled by the diffuse factor (ApplyLight).
//
// Materials: the texture of stage 0 comes with a material map on unit 3 (u_normalMap). When
// generated by the engine (u_material.w != 0) it holds the tangent-space normal in rg, the
// height in b (parallax occlusion mapping) and the glossiness in a (Blinn-Phong specular of
// the lights); a <name>_n.* file supplied by a mod holds a plain rgb normal map.
// u_material = (parallax depth scale, gloss scale, metalness, generated flag).

#define MAX_LIGHTS 128

uniform sampler2D u_texture0;
uniform sampler2D u_texture1;
uniform sampler2D u_texture2;
uniform ivec2 u_stage0;
uniform ivec2 u_stage1;
uniform ivec2 u_stage2;

uniform int u_fogEnabled;
uniform vec3 u_fogColor;
uniform vec2 u_fogRange; // start, end

uniform int u_pixelLighting;
uniform int u_lightCount;
uniform int u_dynamicLightCount;
uniform vec4 u_lightPos[MAX_LIGHTS];
uniform vec4 u_lightColor[MAX_LIGHTS];
uniform vec3 u_cameraPos;

// Shadows: the first u_shadowCount dynamic lights have a cube map holding the distance
// from the light (normalised by fallend) of the nearest occluder in each direction.
uniform int u_shadowCount;
uniform samplerCube u_shadow0;
uniform samplerCube u_shadow1;
uniform samplerCube u_shadow2;
uniform samplerCube u_shadow3;

// Material map of the current material (texture unit 3), see u_normalMapped
uniform sampler2D u_normalMap;
uniform int u_normalMapped;
uniform float u_normalStrength;
uniform vec4 u_material;
uniform float u_specular; // global specular strength, 0 = off

// Soft particles: blended, depth-tested draws without depth write fade out where they get
// close to the opaque scene (u_depth = the scene depth on unit 8, captured before them).
// u_softMode: 0 = off, 1 = scale rgb (additive blends), 2 = scale alpha, 3 = towards white
// (multiplicative blends).
uniform int u_softMode;
uniform sampler2D u_depth;
uniform vec4 u_projection; // (proj[0][0], proj[1][1], Q, Q * near): view z = Q * near / (Q - z_ndc)
uniform vec2 u_invSize;

in vec4 v_color;
in vec2 v_texcoord0;
in vec2 v_texcoord1;
in vec2 v_texcoord2;
in float v_fogDistance;
in vec3 v_worldPos;
in vec3 v_normal;
in float v_diffuse;

out vec4 fragColor;

// Tunables (a mod can edit this file: F7 reloads it)
const float ParallaxDepth = 0.018;    // uv units of relief at u_material.x == 1 (level geometry)
const float ParallaxRange = 900.0;    // world units beyond which the relief fades out
const float ParallaxEntity = 0.4;     // fraction of it on entities (their textures are atlases)
const int ParallaxSteps = 12;         // linear search steps of the parallax occlusion mapping
const float SoftDistance = 24.0;      // world units over which a particle fades against geometry
const float SpecularStrength = 0.9;   // overall specular scale
const float MinShininess = 12.0;      // Blinn-Phong exponent at gloss 0
const float MaxShininess = 220.0;     // ... and at gloss 1

vec3 combineColor(int op, vec3 tex, vec3 prev) {
	if(op == 1) {
		return tex;
	} else if(op == 2) {
		return min(tex * prev, 1.0);
	} else if(op == 3) {
		return min(tex * prev * 2.0, 1.0);
	} else if(op == 4) {
		return min(tex * prev * 4.0, 1.0);
	}
	return prev;
}

float combineAlpha(int op, float tex, float prev) {
	if(op == 1) {
		return tex;
	} else if(op == 2) {
		return min(tex * prev, 1.0);
	} else if(op == 3) {
		return min(tex * prev * 2.0, 1.0);
	} else if(op == 4) {
		return min(tex * prev * 4.0, 1.0);
	}
	return prev;
}

float shadowDistance(int i, vec3 dir) {
	if(i == 0) {
		return texture(u_shadow0, dir).r;
	} else if(i == 1) {
		return texture(u_shadow1, dir).r;
	} else if(i == 2) {
		return texture(u_shadow2, dir).r;
	}
	return texture(u_shadow3, dir).r;
}

// Fraction of the light reaching this fragment, with a small percentage-closer filter.
// fromLight = fragment - light position, dist = its length, fallend = light range,
// cosangle = cosine between the surface normal and the direction to the light.
float shadowFactor(int i, vec3 fromLight, float dist, float fallend, float cosangle) {
	const vec3 offsets[8] = vec3[8](
		vec3( 1.0,  1.0,  1.0), vec3( 1.0, -1.0,  1.0), vec3(-1.0, -1.0,  1.0), vec3(-1.0,  1.0,  1.0),
		vec3( 1.0,  1.0, -1.0), vec3( 1.0, -1.0, -1.0), vec3(-1.0, -1.0, -1.0), vec3(-1.0,  1.0, -1.0)
	);
	// Filter radius in world units, and the depth change it causes across a slanted surface
	float radius = dist * 0.006;
	float c = max(cosangle, 0.05);
	float slope = sqrt(1.0 - c * c) / c;
	float bias = (2.0 + radius * 1.8 * min(slope, 8.0)) / fallend;
	float current = dist / fallend;
	float lit = 0.0;
	for(int k = 0; k < 8; k++) {
		float stored = shadowDistance(i, fromLight + offsets[k] * radius);
		lit += (current - bias <= stored) ? 1.0 : 0.0;
	}
	return lit * (1.0 / 8.0);
}

// Tangent frame of the surface from the screen-space derivatives of the world position and
// texture coordinates (cotangent frame, C. Schüler), so no per-vertex tangents are needed.
// Returns false for a degenerate uv mapping.
bool tangentFrame(vec3 normal, out mat3 tbn) {
	vec3 dp1 = dFdx(v_worldPos);
	vec3 dp2 = dFdy(v_worldPos);
	vec2 duv1 = dFdx(v_texcoord0);
	vec2 duv2 = dFdy(v_texcoord0);
	vec3 dp2perp = cross(dp2, normal);
	vec3 dp1perp = cross(normal, dp1);
	vec3 tangent = dp2perp * duv1.x + dp1perp * duv2.x;
	vec3 bitangent = dp2perp * duv1.y + dp1perp * duv2.y;
	float invmax = inversesqrt(max(dot(tangent, tangent), dot(bitangent, bitangent)));
	if(invmax > 1e6) {
		return false;
	}
	tbn = mat3(tangent * invmax, bitangent * invmax, normal);
	return true;
}

// Parallax occlusion mapping: where the view ray enters the relief stored in the height
// channel of the material map. viewTS = direction towards the camera in tangent space.
vec2 parallaxUv(vec2 uv, vec3 viewTS, float depth) {
	if(depth <= 0.0 || viewTS.z <= 0.05) {
		return uv;
	}
	// Fewer layers head-on, more at grazing angles (where the offset is large)
	float layers = mix(float(ParallaxSteps), float(ParallaxSteps) * 2.0, 1.0 - viewTS.z);
	float layerDepth = 1.0 / layers;
	// Offset per layer: the ray goes down into the surface, away from the camera
	vec2 delta = -viewTS.xy / viewTS.z * depth * layerDepth;
	// Explicit gradients: derivatives are undefined inside the loop
	vec2 ddx = dFdx(uv);
	vec2 ddy = dFdy(uv);
	float currentDepth = 0.0;
	vec2 currentUv = uv;
	float surface = 1.0 - textureGrad(u_normalMap, currentUv, ddx, ddy).b;
	float previousSurface = surface;
	for(int i = 0; i < 2 * ParallaxSteps; i++) {
		if(currentDepth >= surface || float(i) >= layers) {
			break;
		}
		currentUv += delta;
		currentDepth += layerDepth;
		previousSurface = surface;
		surface = 1.0 - textureGrad(u_normalMap, currentUv, ddx, ddy).b;
	}
	// Interpolate between the last two layers where the ray crossed the surface
	float after = surface - currentDepth;
	float before = previousSurface - (currentDepth - layerDepth);
	float weight = after / (after - before + 1e-5);
	return mix(currentUv, currentUv - delta, clamp(weight, 0.0, 1.0));
}

#ifdef ARX_RT
// ArxModern RT (built with rt_common.glsl, "#define ARX_RT"): the shadows of the dynamic lights
// are traced through the level geometry, several rays per light towards a disc the size of
// the flame (soft edges). The cube maps then only hold the entities.
uniform int u_rtShadows;
uniform int u_rtDebug; // 1: show the traced shadow factor of the lights (post_debug=rtshadow)
const int ShadowRays = 4;        // traced rays per light and fragment in the penumbra
const float ShadowMinLight = 0.02; // lights contributing less than this are not traced
const float PenumbraRange = 900.0; // world units from the camera within which the penumbra is refined
const float LightRadius = 12.0;  // world units: size of the light source (penumbra width)

// Interleaved gradient noise (Jimenez 2014): rotates the sample pattern per pixel
float rtNoise(vec2 p) {
	return fract(52.9829189 * fract(0.06711056 * p.x + 0.00583715 * p.y));
}

// Rays from points spread over a disc (the light) to the fragment: the first two are opposite
// each other and settle most fragments (fully lit or fully in the umbra), the rest refine the
// penumbra. Traced from the light so that the back faces it may sit behind (a sconce, a log
// pile) are ignored (rt_common.glsl).
float tracedShadow(vec3 origin, vec3 lightPos, vec3 toLight, float cameraDistance) {
	vec3 up = (abs(toLight.y) < 0.9) ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
	vec3 tx = normalize(cross(up, toLight));
	vec3 ty = cross(toLight, tx);
	float noise = rtNoise(gl_FragCoord.xy);
	// The penumbra detail is not worth it far away
	int rays = (cameraDistance < PenumbraRange) ? ShadowRays : 2;
	float lit = 0.0;
	for(int k = 0; k < rays; k++) {
		if(k == 2 && (lit == 0.0 || lit == 2.0)) {
			return lit * 0.5;
		}
		// Two opposite points at mid radius first, then a spiral over the disc (golden angle);
		// the whole pattern rotated per pixel
		float angle = noise * 6.2831853 + ((k < 2) ? float(k) * 3.14159265 : float(k) * 2.399963);
		float radius = LightRadius * ((k < 2) ? 0.7 : sqrt((float(k) + 0.5) / float(ShadowRays)));
		if(rtLit(lightPos + (tx * cos(angle) + ty * sin(angle)) * radius, origin)) {
			lit += 1.0;
		}
	}
	return lit / float(rays);
}
#endif

// Linear view depth of the scene behind this fragment (soft particles)
float sceneDepthAt(vec2 uv) {
	float zNdc = texture(u_depth, uv).r * 2.0 - 1.0;
	return u_projection.w / (u_projection.z - zNdc);
}

void main() {

	vec4 color = v_color;
	vec2 uv0 = v_texcoord0;
	// Gradients of the stage 0 coordinates, taken before any branch (parallax moves uv0)
	vec2 ddx0 = dFdx(v_texcoord0);
	vec2 ddy0 = dFdy(v_texcoord0);

	int lightCount = 0;
	float lightScale = 0.0;
	if(u_pixelLighting != 0) {
		lightCount = u_dynamicLightCount;
		lightScale = 0.5;
	} else if(v_diffuse > 0.0) {
		lightCount = u_lightCount;
		lightScale = v_diffuse;
	}

	vec3 specular = vec3(0.0);
#ifdef ARX_RT
	float debugShadow = 1.0;
	vec3 debugBlocker = vec3(1.0);
#endif
	if(lightCount > 0) {
		vec3 normal = normalize(v_normal);
		vec3 geometric = normal;
		vec3 toCamera = u_cameraPos - v_worldPos;
		vec3 view = normalize(toCamera);
		float gloss = 0.0;
		mat3 tbn;
		if(u_normalMapped != 0 && tangentFrame(normal, tbn)) {
			if(u_material.w != 0.0) {
				// Generated map: relief in the height channel, gloss in the alpha channel
				float depth = ParallaxDepth * u_material.x * ((u_pixelLighting != 0) ? 1.0 : ParallaxEntity);
				// Only worth it up close, and toned down at grazing angles (the tangent frames of
				// neighbouring polygons differ, a large offset would show their seams)
				depth *= clamp(1.0 - length(toCamera) / ParallaxRange, 0.0, 1.0);
				vec3 viewTS = normalize(vec3(dot(toCamera, tbn[0]), dot(toCamera, tbn[1]), dot(toCamera, tbn[2])));
				depth *= smoothstep(0.0, 0.5, viewTS.z);
				uv0 = parallaxUv(uv0, viewTS, depth);
				vec4 material = textureGrad(u_normalMap, uv0, ddx0, ddy0);
				vec3 n = vec3(material.rg * 2.0 - 1.0, 0.0);
				n.z = sqrt(max(1.0 - dot(n.xy, n.xy), 0.0));
				n.xy *= u_normalStrength;
				normal = normalize(tbn * n);
				gloss = material.a * u_material.y;
			} else {
				vec3 n = texture(u_normalMap, uv0).xyz * 2.0 - 1.0;
				n.xy *= u_normalStrength;
				normal = normalize(tbn * n);
				gloss = u_material.y;
			}
		}
		float shininess = mix(MinShininess, MaxShininess, gloss);
		// Fresnel: brighter highlights at grazing angles
		float facing = max(dot(normal, view), 0.0);
		float fresnel = pow(1.0 - facing, 5.0);
		vec3 light = vec3(0.0);
		for(int i = 0; i < lightCount; i++) {
			vec3 toLight = u_lightPos[i].xyz - v_worldPos;
			float dist = length(toLight);
			float fallend = u_lightColor[i].w;
			if(dist >= fallend) {
				continue;
			}
			toLight /= dist;
			float cosangle = dot(normal, toLight);
			if(cosangle <= 0.0) {
				continue;
			}
			float fallstart = u_lightPos[i].w;
			float attenuation = (dist <= fallstart) ? 1.0 : (fallend - dist) / (fallend - fallstart);
#ifdef ARX_RT
			if(u_rtShadows != 0 && max(max(u_lightColor[i].r, u_lightColor[i].g), u_lightColor[i].b) * cosangle * attenuation * lightScale >= ShadowMinLight) {
				float traced = tracedShadow(v_worldPos + geometric * (1.0 + dist * 0.004), u_lightPos[i].xyz, toLight, length(toCamera));
				debugShadow = min(debugShadow, traced);
				if(u_rtDebug == 2) {
					// One ray from the light centre; the blocker's texture index as a colour
					if(!rtLit(u_lightPos[i].xyz, v_worldPos + geometric * (1.0 + dist * 0.004))) {
						debugBlocker = min(debugBlocker, vec3(float(i) / 8.0, 0.0, 0.0));
					}
				}
				attenuation *= traced;
				if(attenuation <= 0.0) {
					continue;
				}
			}
#endif
			if(i < u_shadowCount) {
				// Offset along the normal so that a surface does not shadow itself
				vec3 fromLight = (v_worldPos + normal * (2.0 + dist * 0.01)) - u_lightPos[i].xyz;
				attenuation *= shadowFactor(i, fromLight, length(fromLight), fallend, cosangle);
				if(attenuation <= 0.0) {
					continue;
				}
			}
			light += u_lightColor[i].rgb * (cosangle * attenuation);
			if(gloss > 0.0 && u_specular > 0.0) {
				vec3 halfway = normalize(toLight + view);
				float s = pow(max(dot(normal, halfway), 0.0), shininess) * (shininess + 8.0) * 0.02;
				specular += u_lightColor[i].rgb * (s * attenuation);
			}
		}
		color.rgb = min(color.rgb + light * lightScale, 1.0);
		specular *= gloss * SpecularStrength * u_specular * lightScale * 2.0 * (1.0 + 2.0 * fresnel);
	}

	vec3 albedo = vec3(1.0);
	if(u_stage0.x != 0 || u_stage0.y != 0) {
		vec4 tex = textureGrad(u_texture0, uv0, ddx0, ddy0);
		albedo = tex.rgb;
		color.rgb = combineColor(u_stage0.x, tex.rgb, color.rgb);
		color.a = combineAlpha(u_stage0.y, tex.a, color.a);
	}

	if(u_stage1.x != 0 || u_stage1.y != 0) {
		vec4 tex = texture(u_texture1, v_texcoord1);
		color.rgb = combineColor(u_stage1.x, tex.rgb, color.rgb);
)glsl" R"glsl(		color.a = combineAlpha(u_stage1.y, tex.a, color.a);
	}

	if(u_stage2.x != 0 || u_stage2.y != 0) {
		vec4 tex = texture(u_texture2, v_texcoord2);
		color.rgb = combineColor(u_stage2.x, tex.rgb, color.rgb);
		color.a = combineAlpha(u_stage2.y, tex.a, color.a);
	}

	// Highlights: white on dielectrics, tinted by the surface on metals
	color.rgb += specular * mix(vec3(1.0), albedo, u_material.z);

	if(u_fogEnabled != 0) {
		// Linear fog, evaluated per fragment (the fixed-function result differs by a few
		// 8-bit steps in the distance, see README)
		float fog = clamp((u_fogRange.y - v_fogDistance) / (u_fogRange.y - u_fogRange.x), 0.0, 1.0);
		color.rgb = mix(u_fogColor, color.rgb, fog);
	}

	if(u_softMode != 0) {
		float sceneZ = sceneDepthAt(gl_FragCoord.xy * u_invSize);
		float fade = clamp((sceneZ - v_fogDistance) / SoftDistance, 0.0, 1.0);
		if(u_softMode == 1) {
			color.rgb *= fade;
		} else if(u_softMode == 2) {
			color.a *= fade;
		} else {
			color.rgb = mix(vec3(1.0), color.rgb, fade);
		}
	}

#ifdef ARX_RT
	if(u_rtDebug == 1) {
		color.rgb = vec3(debugShadow);
	} else if(u_rtDebug == 2) {
		color.rgb = debugBlocker;
		color.a = debugShadow;
	}
#endif

	fragColor = color;

}
)glsl";

constexpr const char * legacy_vert = R"glsl(#version 130

// ArxModern "legacy" vertex shader: reproduces the fixed-function transform.
//
// u_transform == 0 : vertices are pre-transformed (TexturedVertex, screen space with w),
//                    u_mvp maps pixels to clip space and the fog distance is the vertex w.
// u_transform == 1 : vertices are in world space, u_mvp = projection * view.

uniform mat4 u_mvp;
uniform mat4 u_view;
uniform int u_transform;

in vec4 a_position;
in vec4 a_color;
in vec2 a_texcoord0;
in vec2 a_texcoord1;
in vec2 a_texcoord2;
in vec4 a_normal;   // xyz = normal, w = diffuse factor (pre-transformed vertices only)
in vec3 a_worldPos; // pre-transformed vertices only

out vec4 v_color;
out vec2 v_texcoord0;
out vec2 v_texcoord1;
out vec2 v_texcoord2;
out float v_fogDistance;
out vec3 v_worldPos;
out vec3 v_normal;
out float v_diffuse;

void main() {

	gl_Position = u_mvp * a_position;

	v_color = a_color;
	v_texcoord0 = a_texcoord0;
	v_texcoord1 = a_texcoord1;
	v_texcoord2 = a_texcoord2;
	v_normal = a_normal.xyz;
	if(u_transform == 0) {
		v_worldPos = a_worldPos;
		v_diffuse = a_normal.w;
	} else {
		v_worldPos = a_position.xyz;
		v_diffuse = 0.0;
	}

	if(u_transform == 0) {
		// clip.w == view.z for pre-transformed vertices
		v_fogDistance = a_position.w;
	} else {
		// absolute eye-plane distance: the engine's view space looks down +z (D3D style),
		// and the fixed-function pipeline fogs with |z_eye| (GL_EYE_PLANE_ABSOLUTE_NV)
		v_fogDistance = abs((u_view * vec4(a_position.xyz, 1.0)).z);
	}

}
)glsl";

constexpr const char * post_vert = R"glsl(#version 130

// ArxModern post-processing: full-screen triangle generated from the vertex id, no attributes.

out vec2 v_uv;

void main() {
	vec2 p = vec2((gl_VertexID == 1) ? 3.0 : -1.0, (gl_VertexID == 2) ? 3.0 : -1.0);
	v_uv = p * 0.5 + 0.5;
	gl_Position = vec4(p, 0.0, 1.0);
}
)glsl";

constexpr const char * post_blur_frag = R"glsl(#version 130

// ArxModern bloom, pass 2: separable Gaussian blur; u_direction = (1/width, 0) or (0, 1/height).

uniform sampler2D u_source;
uniform vec2 u_direction;

in vec2 v_uv;
out vec4 fragColor;

void main() {
	const float weights[5] = float[5](0.227027, 0.1945946, 0.1216216, 0.054054, 0.016216);
	vec4 result = texture(u_source, v_uv) * weights[0];
	for(int i = 1; i < 5; i++) {
		vec2 offset = u_direction * float(i);
		result += texture(u_source, v_uv + offset) * weights[i];
		result += texture(u_source, v_uv - offset) * weights[i];
	}
	fragColor = result;
}
)glsl";

constexpr const char * post_extract_frag = R"glsl(#version 130

// ArxModern bloom, pass 1: keep what is brighter than the threshold (downsampled to half size).

uniform sampler2D u_scene;
uniform float u_threshold;

in vec2 v_uv;
out vec4 fragColor;

void main() {
	vec3 c = texture(u_scene, v_uv).rgb;
	float luma = dot(c, vec3(0.299, 0.587, 0.114));
	float amount = smoothstep(u_threshold, 1.0, luma);
	fragColor = vec4(c * amount, 1.0);
}
)glsl";

constexpr const char * post_final_frag = R"glsl(#version 130

// ArxModern post-processing, final pass: scene + bloom, then FXAA. Written to the window.
//
// u_bloom      : bloom intensity (0 disables)
// u_ao         : ambient occlusion strength (0 disables)
// u_darkness   : 0..1, how much the dark places are pushed towards black (the "Ambiance" option:
//                what the static lighting left dim becomes really dark, only the torches, spells
//                and lit areas keep their brightness)
// u_fxaa       : 1 to enable the anti-aliasing filter
// u_invSize    : 1 / window size in pixels

uniform sampler2D u_scene;
uniform sampler2D u_bloomTexture;
uniform sampler2D u_aoTexture;
uniform sampler2D u_volumeTexture; // rgb = in-scattered light, a = transmittance (post_volume.frag)
uniform int u_volumetric;
uniform float u_bloom;
uniform float u_ao;       // ambient occlusion strength (0 disables)
uniform float u_darkness;
uniform int u_fxaa;
uniform vec2 u_invSize;
uniform int u_debug;      // 1 = show the ambient occlusion buffer, 2 = the bloom buffer

in vec2 v_uv;
out vec4 fragColor;

// Tunables (a mod can edit this file: F7 reloads it)
const float DarkKnee = 0.4; // luma below which the darkness curve bites (above: untouched)

float luma(vec3 c) {
	return dot(c, vec3(0.299, 0.587, 0.114));
}

vec3 sceneAt(vec2 uv) {
	vec3 c = texture(u_scene, uv).rgb;
	if(u_ao > 0.0) {
		c *= mix(1.0, texture(u_aoTexture, uv).r, u_ao);
	}
	if(u_volumetric != 0) {
		vec4 haze = texture(u_volumeTexture, uv);
		c = c * haze.a + haze.rgb;
	}
	if(u_darkness > 0.0) {
		// Smooth toe: the darker a pixel already is, the more it is pulled towards black
		float l = luma(c);
		c *= mix(1.0, smoothstep(0.0, DarkKnee, l), u_darkness);
	}
	if(u_bloom > 0.0) {
		c += texture(u_bloomTexture, uv).rgb * u_bloom;
	}
	return c;
}

// Compact FXAA (after Timothy Lottes' FXAA 3.11, console/quality style)
vec3 fxaa(vec2 uv) {
	const float EDGE_THRESHOLD_MIN = 0.0312;
	const float EDGE_THRESHOLD_MAX = 0.125;
	const float SUBPIXEL_QUALITY = 0.75;
	const int ITERATIONS = 8;

	vec3 colorCenter = sceneAt(uv);
	float lumaCenter = luma(colorCenter);
	float lumaDown  = luma(sceneAt(uv + vec2(0.0, -u_invSize.y)));
	float lumaUp    = luma(sceneAt(uv + vec2(0.0,  u_invSize.y)));
	float lumaLeft  = luma(sceneAt(uv + vec2(-u_invSize.x, 0.0)));
	float lumaRight = luma(sceneAt(uv + vec2( u_invSize.x, 0.0)));

	float lumaMin = min(lumaCenter, min(min(lumaDown, lumaUp), min(lumaLeft, lumaRight)));
	float lumaMax = max(lumaCenter, max(max(lumaDown, lumaUp), max(lumaLeft, lumaRight)));
	float lumaRange = lumaMax - lumaMin;
	if(lumaRange < max(EDGE_THRESHOLD_MIN, lumaMax * EDGE_THRESHOLD_MAX)) {
		return colorCenter;
	}

	float lumaDownLeft  = luma(sceneAt(uv + vec2(-u_invSize.x, -u_invSize.y)));
	float lumaUpRight   = luma(sceneAt(uv + vec2( u_invSize.x,  u_invSize.y)));
	float lumaUpLeft    = luma(sceneAt(uv + vec2(-u_invSize.x,  u_invSize.y)));
	float lumaDownRight = luma(sceneAt(uv + vec2( u_invSize.x, -u_invSize.y)));

	float lumaDownUp = lumaDown + lumaUp;
	float lumaLeftRight = lumaLeft + lumaRight;
	float lumaLeftCorners = lumaDownLeft + lumaUpLeft;
	float lumaDownCorners = lumaDownLeft + lumaDownRight;
	float lumaRightCorners = lumaDownRight + lumaUpRight;
	float lumaUpCorners = lumaUpRight + lumaUpLeft;

	float edgeHorizontal = abs(-2.0 * lumaLeft + lumaLeftCorners) + abs(-2.0 * lumaCenter + lumaDownUp) * 2.0
	                     + abs(-2.0 * lumaRight + lumaRightCorners);
	float edgeVertical = abs(-2.0 * lumaUp + lumaUpCorners) + abs(-2.0 * lumaCenter + lumaLeftRight) * 2.0
	                   + abs(-2.0 * lumaDown + lumaDownCorners);
	bool isHorizontal = (edgeHorizontal >= edgeVertical);

	float luma1 = isHorizontal ? lumaDown : lumaLeft;
	float luma2 = isHorizontal ? lumaUp : lumaRight;
	float gradient1 = luma1 - lumaCenter;
	float gradient2 = luma2 - lumaCenter;
	bool is1Steepest = abs(gradient1) >= abs(gradient2);
	float gradientScaled = 0.25 * max(abs(gradient1), abs(gradient2));

	float stepLength = isHorizontal ? u_invSize.y : u_invSize.x;
	float lumaLocalAverage = 0.0;
	if(is1Steepest) {
		stepLength = -stepLength;
		lumaLocalAverage = 0.5 * (luma1 + lumaCenter);
	} else {
		lumaLocalAverage = 0.5 * (luma2 + lumaCenter);
	}

	vec2 currentUv = uv;
	if(isHorizontal) {
		currentUv.y += stepLength * 0.5;
	} else {
		currentUv.x += stepLength * 0.5;
	}

	vec2 offset = isHorizontal ? vec2(u_invSize.x, 0.0) : vec2(0.0, u_invSize.y);
	vec2 uv1 = currentUv - offset;
	vec2 uv2 = currentUv + offset;
	float lumaEnd1 = luma(sceneAt(uv1)) - lumaLocalAverage;
	float lumaEnd2 = luma(sceneAt(uv2)) - lumaLocalAverage;
	bool reached1 = abs(lumaEnd1) >= gradientScaled;
	bool reached2 = abs(lumaEnd2) >= gradientScaled;
	bool reachedBoth = reached1 && reached2;
	if(!reached1) {
		uv1 -= offset;
	}
	if(!reached2) {
		uv2 += offset;
	}

	if(!reachedBoth) {
		for(int i = 2; i < ITERATIONS; i++) {
			if(!reached1) {
				lumaEnd1 = luma(sceneAt(uv1)) - lumaLocalAverage;
			}
			if(!reached2) {
				lumaEnd2 = luma(sceneAt(uv2)) - lumaLocalAverage;
			}
			reached1 = abs(lumaEnd1) >= gradientScaled;
			reached2 = abs(lumaEnd2) >= gradientScaled;
			reachedBoth = reached1 && reached2;
			float quality = (i < 5) ? 1.5 : ((i < 7) ? 2.0 : 4.0);
			if(!reached1) {
				uv1 -= offset * quality;
			}
			if(!reached2) {
				uv2 += offset * quality;
			}
			if(reachedBoth) {
				break;
			}
		}
	}

	float distance1 = isHorizontal ? (uv.x - uv1.x) : (uv.y - uv1.y);
	float distance2 = isHorizontal ? (uv2.x - uv.x) : (uv2.y - uv.y);
	bool isDirection1 = distance1 < distance2;
	float distanceFinal = min(distance1, distance2);
	float edgeThickness = (distance1 + distance2);
	float pixelOffset = -distanceFinal / edgeThickness + 0.5;

	bool isLumaCenterSmaller = lumaCenter < lumaLocalAverage;
	bool correctVariation = ((isDirection1 ? lumaEnd1 : lumaEnd2) < 0.0) != isLumaCenterSmaller;
	float finalOffset = correctVariation ? pixelOffset : 0.0;

	float lumaAverage = (1.0 / 12.0) * (2.0 * (lumaDownUp + lumaLeftRight) + lumaLeftCorners + lumaRightCorners);
	float subPixelOffset1 = clamp(abs(lumaAverage - lumaCenter) / lumaRange, 0.0, 1.0);
	float subPixelOffset2 = (-2.0 * subPixelOffset1 + 3.0) * subPixelOffset1 * subPixelOffset1;
	float subPixelOffsetFinal = subPixelOffset2 * subPixelOffset2 * SUBPIXEL_QUALITY;
	finalOffset = max(finalOffset, subPixelOffsetFinal);

	vec2 finalUv = uv;
	if(isHorizontal) {
		finalUv.y += finalOffset * stepLength;
	} else {
		finalUv.x += finalOffset * stepLength;
	}
	return sceneAt(finalUv);
}

void main() {
	if(u_debug == 1) {
		fragColor = vec4(texture(u_aoTexture, v_uv).rrr, 1.0);
		return;
	} else if(u_debug == 2) {
		fragColor = vec4(texture(u_bloomTexture, v_uv).rgb, 1.0);
		return;
	} else if(u_debug == 3) {
		fragColor = vec4(texture(u_volumeTexture, v_uv).rgb * 4.0, 1.0);
		return;
	}
	vec3 c = (u_fxaa != 0) ? fxaa(v_uv) : sceneAt(v_uv);
	fragColor = vec4(c, 1.0);
}
)glsl";

constexpr const char * post_ssao_frag = R"glsl(#version 130

// ArxModern screen-space ambient occlusion, computed at half resolution from the scene depth.
//
// The engine's projection (game/Camera.cpp) is D3D-style: z_clip = Q * z - Q * near, w_clip = z,
// so the linear view depth is  z = Q * near / (Q - z_ndc).
// u_projection = (proj[0][0], proj[1][1], Q, Q * near)

uniform sampler2D u_depth;
uniform vec4 u_projection;
uniform vec2 u_invSize;   // 1 / depth texture size
uniform float u_radius;   // world units
uniform float u_bias;     // world units

in vec2 v_uv;
out vec4 fragColor;

// Tunables (a mod can edit this file: F7 reloads it)
const float CreaseTolerance = 0.08; // ~4.5 degrees between neighbouring polygons ignored

float linearDepth(vec2 uv) {
	float d = texture(u_depth, uv).r;
	float zNdc = d * 2.0 - 1.0;
	return u_projection.w / (u_projection.z - zNdc);
}

vec3 viewPosition(vec2 uv) {
	float z = linearDepth(uv);
	vec2 ndc = uv * 2.0 - 1.0;
	return vec3(ndc.x * z / u_projection.x, ndc.y * z / u_projection.y, z);
}

float hash(vec2 p) {
	return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {

	vec3 position = viewPosition(v_uv);
	if(position.z >= 0.98 * (u_projection.w / (u_projection.z - 1.0))) {
		// far plane (background): no occlusion
		fragColor = vec4(1.0);
		return;
	}

	// Normal from the depth derivatives. On each axis the side whose two neighbours extrapolate
	// best to this depth is used, so that depth discontinuities (silhouettes, and the small steps
	// between the floor tiles of the levels, which showed as dark lines) do not tilt the normal
	vec3 right = viewPosition(v_uv + vec2(u_invSize.x, 0.0));
	vec3 left = viewPosition(v_uv - vec2(u_invSize.x, 0.0));
	vec3 up = viewPosition(v_uv + vec2(0.0, u_invSize.y));
	vec3 down = viewPosition(v_uv - vec2(0.0, u_invSize.y));
	float right2 = linearDepth(v_uv + vec2(2.0 * u_invSize.x, 0.0));
	float left2 = linearDepth(v_uv - vec2(2.0 * u_invSize.x, 0.0));
	float up2 = linearDepth(v_uv + vec2(0.0, 2.0 * u_invSize.y));
	float down2 = linearDepth(v_uv - vec2(0.0, 2.0 * u_invSize.y));
	float errRight = abs(2.0 * right.z - right2 - position.z);
	float errLeft = abs(2.0 * left.z - left2 - position.z);
	float errUp = abs(2.0 * up.z - up2 - position.z);
	float errDown = abs(2.0 * down.z - down2 - position.z);
	vec3 dx = (errRight < errLeft) ? (right - position) : (position - left);
	vec3 dy = (errUp < errDown) ? (up - position) : (position - down);
	vec3 normal = normalize(cross(dx, dy));
	if(dot(normal, -position) < 0.0) {
		normal = -normal;
	}

	// Random rotation around the normal
	float angle = hash(gl_FragCoord.xy) * 6.2831853;
	vec3 randomVec = vec3(cos(angle), sin(angle), 0.0);
	vec3 tangent = normalize(randomVec - normal * dot(randomVec, normal));
	vec3 bitangent = cross(normal, tangent);

	const int SAMPLES = 12;
	const vec3 kernel[12] = vec3[12](
		vec3( 0.2024,  0.8412, 0.4986), vec3(-0.2201, -0.1682, 0.5311), vec3( 0.1226,  0.0455, 0.1096),
		vec3(-0.0621,  0.2264, 0.2044), vec3( 0.6421, -0.0826, 0.4063), vec3(-0.3846, -0.4783, 0.3162),
		vec3( 0.0392, -0.1149, 0.0894), vec3(-0.7148,  0.2186, 0.3517), vec3( 0.2937,  0.3341, 0.1802),
		vec3(-0.1108, -0.0361, 0.0640), vec3( 0.5011, -0.6096, 0.2270), vec3(-0.3212,  0.0855, 0.0985)
	);

	float occlusion = 0.0;
	for(int i = 0; i < SAMPLES; i++) {
		vec3 k = kernel[i];
		vec3 samplePos = position + (tangent * k.x + bitangent * k.y + normal * k.z) * u_radius;
		if(samplePos.z <= 0.0) {
			continue;
		}
		// Project back to screen
		vec2 sampleUv = vec2(samplePos.x * u_projection.x / samplePos.z, samplePos.y * u_projection.y / samplePos.z) * 0.5 + 0.5;
		if(sampleUv.x < 0.0 || sampleUv.x > 1.0 || sampleUv.y < 0.0 || sampleUv.y > 1.0) {
			continue;
		}
		float sceneZ = linearDepth(sampleUv);
		float rangeCheck = smoothstep(0.0, 1.0, u_radius / abs(position.z - sceneZ));
		// Depth precision drops with distance: grow the bias with it. And the floors of the levels
		// are not quite flat: adjacent tiles meet at a slight angle, which must not read as a
		// crease (dark lines along the seams) - tolerate a few degrees over the sample distance
		float bias = u_bias + position.z * 0.004 + length(k) * u_radius * CreaseTolerance;
		occlusion += ((sceneZ <= samplePos.z - bias) ? 1.0 : 0.0) * rangeCheck;
	}

	float ao = 1.0 - occlusion / float(SAMPLES);
	fragColor = vec4(ao, ao, ao, 1.0);
}
)glsl";

constexpr const char * post_volume_frag = R"glsl(#version 130

// ArxModern volumetric fog, computed at half resolution from the scene depth.
// (Built with a "#version 430" / ARX_RT prelude when the ray tracing is on: the version line
// above is then dropped.)
//
// The air of the levels becomes a thin, drifting haze: along the ray of every pixel the light
// of the scene's torches, sconces and spells is scattered towards the camera (light shafts and
// halos), and what lies behind the haze is dimmed by it. With the ray tracing built in (ARX_RT,
// rt_common.glsl prepended) the shafts are shadowed by the level geometry: the light of a
// sconce round a corner does not glow through the wall.
//
// Output: rgb = in-scattered light, a = transmittance (post_final.frag composes
// scene * a + rgb). u_projection = (proj[0][0], proj[1][1], Q, Q * near) as in post_ssao.frag.

#define MAX_LIGHTS 128

uniform sampler2D u_depth;
uniform vec4 u_projection;
uniform mat4 u_invView;     // view -> world
uniform vec3 u_cameraPos;
uniform float u_density;    // 0..1, the "Haze" option
uniform float u_lightScale; // strength of the light scattered by the haze (the shafts and their shadows)
uniform float u_time;
uniform int u_lightCount;   // every light of the scene (the static sconces too), like the water pass
uniform vec4 u_lightPos[MAX_LIGHTS];   // xyz, fallstart
uniform vec4 u_lightColor[MAX_LIGHTS]; // rgb, fallend
uniform int u_shadows;      // 1: trace the shafts' shadows (ARX_RT only)
// The shadow cube maps of the first lights (the characters and objects standing in the light -
// and the level too without the ray tracing): distance of the nearest occluder from the light,
// normalised by its range, as in legacy.frag. u_lightShadow[i] = which cube map, or -1
uniform int u_lightShadow[MAX_LIGHTS];
uniform samplerCube u_shadow0;
uniform samplerCube u_shadow1;
uniform samplerCube u_shadow2;
uniform samplerCube u_shadow3;

in vec2 v_uv;
out vec4 fragColor;

// Tunables (a mod can edit this file: F7 reloads it)
const int Steps = 12;               // samples along each ray
const float MaxRange = 3000.0;      // world units of haze in front of the camera
const float RangeFade = 0.5;        // fraction of the range from which the haze thins out
const float Extinction = 0.00015;   // per world unit at density 1: how much the haze dims what is behind
const float Scatter = 0.0008;       // per world unit at density 1: how much light it throws back
const float GlowCompression = 2.0;  // the brighter the glow, the more it is held back (soft ceiling)
const float Ambient = 0.006;        // faint glow of the haze where no light reaches (low: the shadows in the beams read better)
const float Anisotropy = 0.35;      // Henyey-Greenstein g: > 0 scatters forward (halos round the lights)
const float NoiseScale = 0.0035;    // world units -> noise; smaller = larger wisps
const float NoiseAmount = 0.75;     // 0 = uniform haze, 1 = strongly wispy
const float Drift = 0.05;           // wisps drifting speed
const int MaxLightsPerRay = 12;     // the strongest lights on the ray only
const float HiddenWeight = 0.25;    // ranking weight kept by a light hidden where the ray passes closest
const float MinFalloff = 0.35;      // fraction of a light's range over which it fades at least

float linearDepth(vec2 uv) {
	float zNdc = texture(u_depth, uv).r * 2.0 - 1.0;
	return u_projection.w / (u_projection.z - zNdc);
}

float hash(vec3 p) {
	p = fract(p * 0.3183099 + vec3(0.1, 0.17, 0.23));
	p *= 17.0;
	return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

// Smooth value noise, 0..1
float noise(vec3 p) {
	vec3 i = floor(p);
	vec3 f = fract(p);
	f = f * f * (3.0 - 2.0 * f);
	return mix(mix(mix(hash(i), hash(i + vec3(1.0, 0.0, 0.0)), f.x),
	               mix(hash(i + vec3(0.0, 1.0, 0.0)), hash(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
	           mix(mix(hash(i + vec3(0.0, 0.0, 1.0)), hash(i + vec3(1.0, 0.0, 1.0)), f.x),
	               mix(hash(i + vec3(0.0, 1.0, 1.0)), hash(i + vec3(1.0, 1.0, 1.0)), f.x), f.y), f.z);
}

float density(vec3 p) {
	vec3 q = p * NoiseScale + vec3(u_time * Drift, u_time * Drift * 0.3, 0.0);
	float n = noise(q) * 0.65 + noise(q * 2.7 + 3.1) * 0.35;
	return u_density * mix(1.0, n * 1.6, NoiseAmount);
}

float phase(float cosTheta) {
	float g = Anisotropy;
	float d = 1.0 + g * g - 2.0 * g * cosTheta;
	return (1.0 - g * g) / (4.0 * 3.14159265 * d * sqrt(d));
}

// The engine's falloff (constant to fallstart, linear to zero at fallend), but never steeper
// than over a third of the range: some level lights have fallstart right at fallend, which
// would show as a hard-edged ball of haze in the air
float falloff(float dist, float fallstart, float fallend) {
	float width = max(fallend - fallstart, fallend * MinFalloff);
	float f = clamp((fallend - dist) / width, 0.0, 1.0);
	return f * f * (3.0 - 2.0 * f); // eased: a linear edge integrates into a visible rim
}

float shadowDistance(int map, vec3 dir) {
	if(map == 0) {
		return texture(u_shadow0, dir).r;
	} else if(map == 1) {
		return texture(u_shadow1, dir).r;
	} else if(map == 2) {
		return texture(u_shadow2, dir).r;
	}
	return texture(u_shadow3, dir).r;
}

// Whether the point sees the light according to its cube map (what stands in the beam)
bool mapLit(int map, vec3 fromLight, float dist, float fallend) {
	return dist / fallend - 0.01 <= shadowDistance(map, fromLight);
}

// Interleaved gradient noise: offsets the samples per pixel so that the steps do not band
float dither(vec2 p) {
	return fract(52.9829189 * fract(0.06711056 * p.x + 0.00583715 * p.y));
}

void main() {

	// The ray of this pixel, in world space, with t = view depth
	vec2 ndc = v_uv * 2.0 - 1.0;
	vec3 dirView = vec3(ndc.x / u_projection.x, ndc.y / u_projection.y, 1.0);
	vec3 dirWorld = mat3(u_invView) * dirView;
	float dirLength = length(dirWorld);
	vec3 dir = dirWorld / dirLength;
	float range = min(linearDepth(v_uv), MaxRange / dirLength);

	// The lights that matter most for this ray: those whose sphere the ray crosses, ranked by
	// their brightness where the ray passes closest. Keeping the first ones found instead
	// showed the spheres of dim distant lights as circles (a bright light lost its slot inside
	// them) and halos that switched off with the view direction.
	int lights[MaxLightsPerRay];
	float weights[MaxLightsPerRay];
	int lightCount = 0;
	for(int i = 0; i < u_lightCount; i++) {
		vec3 toLight = u_lightPos[i].xyz - u_cameraPos;
		float along = clamp(dot(toLight, dir), 0.0, range * dirLength);
		float away = length(toLight - dir * along);
		float fallend = u_lightColor[i].w;
		if(away >= fallend) {
			continue;
		}
		float weight = falloff(away, u_lightPos[i].w, fallend) * dot(u_lightColor[i].rgb, vec3(0.299, 0.587, 0.114));
#ifdef ARX_RT
		// A bright light hidden behind a wall must not crowd out the lanterns that really shine
		// on this ray (it left dark discs): one ray to where it would matter most weighs it down
		// - softly, so that the ranking does not flip at the edge of the wall's shadow
		if(u_shadows != 0 && !rtLit(u_lightPos[i].xyz, u_cameraPos + dir * along)) {
			weight *= HiddenWeight;
		}
#endif
		// Insert in decreasing weight, dropping the weakest beyond MaxLightsPerRay
		int slot = min(lightCount, MaxLightsPerRay - 1);
		if(lightCount < MaxLightsPerRay || weight > weights[slot]) {
			while(slot > 0 && weights[slot - 1] < weight) {
				lights[slot] = lights[slot - 1];
				weights[slot] = weights[slot - 1];
				slot--;
			}
			lights[slot] = i;
			weights[slot] = weight;
			lightCount = min(lightCount + 1, MaxLightsPerRay);
		}
	}

	float dt = range / float(Steps);
	float t = dt * dither(gl_FragCoord.xy);
	float transmittance = 1.0;
	vec3 inscatter = vec3(0.0);
	for(int s = 0; s < Steps; s++) {
		vec3 p = u_cameraPos + dirWorld * t;
		float stepLength = dt * dirLength;
		// The haze thins out towards the end of its range instead of stopping dead: a light
		// standing just beyond the range showed as a hard disc of glow (the rays ending inside
		// its sphere got it, the others did not)
		float rho = density(p) * (1.0 - smoothstep(MaxRange * RangeFade, MaxRange, t * dirLength));
		vec3 light = vec3(Ambient);
		for(int k = 0; k < lightCount; k++) {
			int i = lights[k];
			vec3 toLight = u_lightPos[i].xyz - p;
			float dist = length(toLight);
			float fallend = u_lightColor[i].w;
			if(dist >= fallend) {
				continue;
			}
			float fallstart = u_lightPos[i].w;
			float attenuation = falloff(dist, fallstart, fallend);
			// Closer to the source than fallstart the light gets stronger still (a flame is small)
			attenuation *= 1.0 + 2.0 * clamp(1.0 - dist / fallstart, 0.0, 1.0);
#ifdef ARX_RT
			if(u_shadows != 0 && !rtLit(u_lightPos[i].xyz, p)) {
				continue;
			}
#endif
			int map = u_lightShadow[i];
			if(map >= 0 && !mapLit(map, -toLight, dist, fallend)) {
				continue;
			}
			light += u_lightColor[i].rgb * (attenuation * phase(dot(toLight / dist, -dir)));
		}
		float extinction = exp(-rho * Extinction * stepLength);
		light = vec3(Ambient) + (light - vec3(Ambient)) * u_lightScale;
		inscatter += transmittance * light * (rho * Scatter * stepLength);
		transmittance *= extinction;
		t += dt;
	}

	// Many lights add up: compress the glow so that a lit hall never washes out to white
	inscatter = inscatter / (1.0 + inscatter * GlowCompression) * (1.0 + GlowCompression);

	fragColor = vec4(inscatter, transmittance);
}
)glsl";

constexpr const char * reflect_frag = R"glsl(#version 130

// ArxModern screen-space reflections.
//
// The glossy level polygons (metal walls, marble and wet floors, ice, glass) are drawn again
// after the opaque scene: from each pixel a ray is reflected off the surface and marched
// through the scene depth buffer; where it hits, the scene colour there is what the surface
// reflects. What is off screen or hidden cannot be reflected: the effect fades out there.
// Blended over the scene with the reflection's own weight (Fresnel and glossiness).
//
// Inputs: u_scene / u_depth = the scene as rendered so far, u_texture0 = the material's
// texture (unit 0), u_normalMap = its material map (unit 3, see legacy.frag), u_material =
// (parallax, gloss scale, metalness, generated flag).

uniform sampler2D u_texture0;
uniform sampler2D u_normalMap;
uniform sampler2D u_scene;
uniform sampler2D u_depth;
uniform mat4 u_proj;
uniform mat4 u_view;
uniform vec4 u_projection; // (proj[0][0], proj[1][1], Q, Q * near): view z = Q * near / (Q - z_ndc)
uniform vec2 u_invSize;
uniform vec4 u_material;
uniform int u_normalMapped;
uniform float u_strength;  // 0..1, overall intensity
uniform int u_fogEnabled;
uniform vec2 u_fogRange;

in vec3 v_worldPos;
in vec3 v_viewPos;
in vec3 v_normal;
in vec2 v_uv;
in vec4 v_color;

out vec4 fragColor;

// Tunables (a mod can edit this file: F7 reloads it)
const int Steps = 24;              // ray march steps
const float FirstStep = 6.0;       // world units
const float StepGrowth = 1.28;     // each step is this much longer than the previous
const float Thickness = 0.12;      // depth tolerance behind the surface hit, fraction of the distance
const float MinThickness = 12.0;   // ... at least this many units
const float MaxReflection = 0.85;  // weight of a perfect mirror at a grazing angle
const float MinReflection = 0.3;   // ... and head-on
const float RoughnessBend = 0.35;  // how much the material map bends the reflected ray

float linearDepth(float zBuffer) {
	float zNdc = zBuffer * 2.0 - 1.0;
	return u_projection.w / (u_projection.z - zNdc);
}

float sceneDepth(vec2 uv) {
	return linearDepth(texture(u_depth, uv).r);
}

// Screen position of a view-space point; w <= 0 when behind the camera
vec3 project(vec3 p) {
	vec4 clip = u_proj * vec4(p, 1.0);
	return vec3(clip.xy / clip.w * 0.5 + 0.5, clip.w);
}

// Cotangent frame from derivatives (see legacy.frag)
bool tangentFrame(vec3 normal, out mat3 tbn) {
	vec3 dp1 = dFdx(v_worldPos);
	vec3 dp2 = dFdy(v_worldPos);
	vec2 duv1 = dFdx(v_uv);
	vec2 duv2 = dFdy(v_uv);
	vec3 dp2perp = cross(dp2, normal);
	vec3 dp1perp = cross(normal, dp1);
	vec3 tangent = dp2perp * duv1.x + dp1perp * duv2.x;
	vec3 bitangent = dp2perp * duv1.y + dp1perp * duv2.y;
	float invmax = inversesqrt(max(dot(tangent, tangent), dot(bitangent, bitangent)));
	if(invmax > 1e6) {
		return false;
	}
	tbn = mat3(tangent * invmax, bitangent * invmax, normal);
	return true;
}

void main() {

	// Glossiness of this texel
	float gloss = u_material.y;
	vec3 normalWorld = normalize(v_normal);
	mat3 tbn;
	bool framed = (u_normalMapped != 0) && tangentFrame(normalWorld, tbn);
	if(framed) {
		vec4 material = texture(u_normalMap, v_uv);
		vec3 n;
		if(u_material.w != 0.0) {
			gloss *= material.a;
			n = vec3(material.rg * 2.0 - 1.0, 0.0);
			n.z = sqrt(max(1.0 - dot(n.xy, n.xy), 0.0));
		} else {
			n = material.xyz * 2.0 - 1.0;
		}
		// A rough surface reflects along a slightly bent normal (blurs the reflection)
		n.xy *= RoughnessBend * (1.0 - gloss);
		normalWorld = normalize(tbn * n);
	}
	if(gloss <= 0.02) {
		discard;
	}

	// Reflected ray in view space (camera at the origin, looking down +z)
	vec3 normal = normalize(mat3(u_view) * normalWorld);
	if(dot(normal, -v_viewPos) < 0.0) {
		normal = -normal; // the polygon is seen from behind
	}
	vec3 view = normalize(-v_viewPos);
	vec3 dir = reflect(-view, normal);

	// Fresnel, lifted head-on so that a glossy floor visibly mirrors (a wet look rather
	// than physically exact)
	float facing = max(dot(normal, view), 0.0);
	float fresnel = pow(1.0 - facing, 4.0);
	float weight = mix(mix(MinReflection, 1.0, fresnel), 1.0, u_material.z * 0.5) * gloss * MaxReflection * u_strength;
	// Rays towards the camera see what is behind it: nothing to show
	weight *= smoothstep(-0.15, 0.25, dir.z);
	if(weight <= 0.005) {
		discard;
	}

	// March
	vec3 p = v_viewPos;
	float step = FirstStep;
	float tPrev = 0.0, t = 0.0;
	bool hit = false;
	vec2 hitUv = vec2(0.0);
	for(int i = 0; i < Steps; i++) {
		tPrev = t;
		t += step;
		step *= StepGrowth;
		vec3 q = p + dir * t;
		vec3 s = project(q);
		if(s.z <= 0.0 || s.x < 0.0 || s.x > 1.0 || s.y < 0.0 || s.y > 1.0) {
			break;
		}
		float sceneZ = sceneDepth(s.xy);
		float behind = q.z - sceneZ;
		if(behind > 0.0 && behind < max(sceneZ * Thickness, MinThickness)) {
			// Refine between the previous and this step
			float a = tPrev, b = t;
			for(int k = 0; k < 5; k++) {
				float m = 0.5 * (a + b);
				vec3 qm = p + dir * m;
				vec3 sm = project(qm);
				if(qm.z > sceneDepth(sm.xy)) {
					b = m;
				} else {
					a = m;
				}
			}
			hitUv = project(p + dir * b).xy;
			hit = true;
			break;
		}
	}
	if(!hit) {
		discard;
	}

	// Fade at the screen edges (the reflection would pop when the source leaves the view)
	vec2 edge = smoothstep(vec2(0.0), vec2(0.12), hitUv) * smoothstep(vec2(0.0), vec2(0.12), 1.0 - hitUv);
	weight *= edge.x * edge.y;

	vec3 reflected = texture(u_scene, hitUv).rgb;
	// Metals tint their reflections
	vec3 albedo = texture(u_texture0, v_uv).rgb;
	reflected *= mix(vec3(1.0), albedo * 1.5, u_material.z);

	if(u_fogEnabled != 0) {
		float fog = clamp((u_fogRange.y - v_viewPos.z) / (u_fogRange.y - u_fogRange.x), 0.0, 1.0);
		weight *= fog;
	}

	fragColor = vec4(reflected, weight);
}
)glsl";

constexpr const char * reflect_vert = R"glsl(#version 130

// ArxModern screen-space reflections: the glossy level polygons (world space, SMY_VERTEX)
// drawn again after the opaque scene, with the scene colour and depth available.

uniform mat4 u_viewProj;
uniform mat4 u_view;

in vec4 a_position;
in vec4 a_color;
in vec2 a_texcoord0;
in vec4 a_normal;

out vec3 v_worldPos;
out vec3 v_viewPos;
out vec3 v_normal;
out vec2 v_uv;
out vec4 v_color;

void main() {
	v_worldPos = a_position.xyz;
	v_viewPos = (u_view * vec4(a_position.xyz, 1.0)).xyz;
	v_normal = a_normal.xyz;
	v_uv = a_texcoord0;
	v_color = a_color;
	gl_Position = u_viewProj * vec4(a_position.xyz, 1.0);
}
)glsl";

constexpr const char * reflect_rt_frag = R"glsl(// ArxModern ray-traced reflections (rt_common.glsl is prepended, "#version 430").
//
// Like reflect.frag, the glossy level polygons are drawn again after the opaque scene, but the
// reflected ray is traced through the level geometry itself instead of the depth buffer: what
// is off screen, behind the camera or hidden behind a pillar reflects too, and the reflection
// no longer fades at the screen edges. Where the point hit is visible on screen the scene
// colour there is used (exact: characters, particles, everything drawn); elsewhere the hit is
// shaded from the level textures, its static light and the dynamic lights (with a shadow ray
// each, so the reflected torches cast shadows).
//
// u_mode 1 is a debugging view (post_debug=rt): every level polygon shows what a ray from the
// camera hits there - it must look like the scene itself, minus the characters.

#define MAX_RT_LIGHTS 32

uniform sampler2D u_texture0;
uniform sampler2D u_normalMap;
uniform sampler2D u_scene;
uniform sampler2D u_depth;
uniform mat4 u_proj;
uniform mat4 u_view;
uniform vec4 u_projection; // (proj[0][0], proj[1][1], Q, Q * near): view z = Q * near / (Q - z_ndc)
uniform vec2 u_invSize;
uniform vec4 u_material;
uniform int u_normalMapped;
uniform float u_strength;  // 0..1, overall intensity
uniform int u_fogEnabled;
uniform vec3 u_fogColor;
uniform vec2 u_fogRange;
uniform vec3 u_cameraPos;
uniform int u_mode;
uniform int u_shadowRays;  // shadow rays towards the dynamic lights at the hit point
uniform int u_lightCount;  // dynamic lights (torches, spells), like legacy.frag
uniform vec4 u_lightPos[MAX_RT_LIGHTS];   // xyz, fallstart
uniform vec4 u_lightColor[MAX_RT_LIGHTS]; // rgb, fallend

in vec3 v_worldPos;
in vec3 v_viewPos;
in vec3 v_normal;
in vec2 v_uv;
in vec4 v_color;

out vec4 fragColor;

// Tunables (a mod can edit this file: F7 reloads it)
const float MaxDistance = 8000.0;  // world units a reflected ray travels at most
const float MaxReflection = 0.85;  // weight of a perfect mirror at a grazing angle
const float MinReflection = 0.3;   // ... and head-on
const float RoughnessBend = 0.35;  // how much the material map bends the reflected ray
const float RoughnessBlur = 3.0;   // texture mip levels of blur on the hit at gloss 0
const float SceneTolerance = 0.03; // depth match (fraction) for reusing the on-screen colour
const float LightScale = 0.5;      // the dynamic lights on level geometry (ApplyTileLights)

float linearDepth(float zBuffer) {
	float zNdc = zBuffer * 2.0 - 1.0;
	return u_projection.w / (u_projection.z - zNdc);
}

// Cotangent frame from derivatives (see legacy.frag)
bool tangentFrame(vec3 normal, out mat3 tbn) {
	vec3 dp1 = dFdx(v_worldPos);
	vec3 dp2 = dFdy(v_worldPos);
	vec2 duv1 = dFdx(v_uv);
	vec2 duv2 = dFdy(v_uv);
	vec3 dp2perp = cross(dp2, normal);
	vec3 dp1perp = cross(normal, dp1);
	vec3 tangent = dp2perp * duv1.x + dp1perp * duv2.x;
	vec3 bitangent = dp2perp * duv1.y + dp1perp * duv2.y;
	float invmax = inversesqrt(max(dot(tangent, tangent), dot(bitangent, bitangent)));
	if(invmax > 1e6) {
		return false;
	}
	tbn = mat3(tangent * invmax, bitangent * invmax, normal);
	return true;
}

// What the level looks like at a hit point, seen along dir (blur = texture mip level)
vec3 shadeHit(RtHit hit, vec3 point, vec3 dir, float blur) {
	uint tri = hit.tri;
	uint flags = rtFlags(tri);
	vec3 albedo = textureLod(u_rtTextures, vec3(rtUv(tri, hit.bary), float(rtLayer(tri))), blur).rgb;
	if((flags & RtGlow) != 0u) {
		return albedo;
	}
	vec3 light = rtColor(tri, hit.bary);
	vec3 normal = normalize(rtNormal(tri));
	if(dot(normal, dir) > 0.0) {
		normal = -normal; // seen from behind
	}
	vec3 dynamic = vec3(0.0);
	for(int i = 0; i < u_lightCount; i++) {
		vec3 toLight = u_lightPos[i].xyz - point;
		float dist = length(toLight);
		float fallend = u_lightColor[i].w;
		if(dist >= fallend) {
			continue;
		}
		toLight /= dist;
		float cosangle = dot(normal, toLight);
		if(cosangle <= 0.0) {
			continue;
		}
		float fallstart = u_lightPos[i].w;
		float attenuation = (dist <= fallstart) ? 1.0 : (fallend - dist) / (fallend - fallstart);
		if(u_shadowRays != 0 && !rtLit(u_lightPos[i].xyz, point + normal * 2.0)) {
			continue;
		}
		dynamic += u_lightColor[i].rgb * (cosangle * attenuation);
	}
	light = min(light + dynamic * LightScale, 1.0);
	return albedo * light;
}

void main() {

	if(u_mode == 1) {
		// Debug: primary rays
		vec3 dir = normalize(v_worldPos - u_cameraPos);
		RtHit hit;
		if(!rtTrace(u_cameraPos, dir, MaxDistance, false, false, hit)) {
			fragColor = vec4(1.0, 0.0, 1.0, 1.0);
			return;
		}
		vec3 point = u_cameraPos + dir * hit.t;
		vec3 color = shadeHit(hit, point, dir, 0.0);
		if(u_fogEnabled != 0) {
			float fog = clamp((u_fogRange.y - hit.t) / (u_fogRange.y - u_fogRange.x), 0.0, 1.0);
			color = mix(u_fogColor, color, fog);
		}
		fragColor = vec4(color, 1.0);
		return;
	}

	// Glossiness of this texel
	float gloss = u_material.y;
	vec3 geometric = normalize(v_normal);
	vec3 normal = geometric;
	mat3 tbn;
	bool framed = (u_normalMapped != 0) && tangentFrame(geometric, tbn);
	if(framed) {
		vec4 material = texture(u_normalMap, v_uv);
		vec3 n;
		if(u_material.w != 0.0) {
			gloss *= material.a;
			n = vec3(material.rg * 2.0 - 1.0, 0.0);
			n.z = sqrt(max(1.0 - dot(n.xy, n.xy), 0.0));
		} else {
			n = material.xyz * 2.0 - 1.0;
		}
		// A rough surface reflects along a slightly bent normal (blurs the reflection)
		n.xy *= RoughnessBend * (1.0 - gloss);
		normal = normalize(tbn * n);
	}
	if(gloss <= 0.02) {
		discard;
	}

	vec3 toCamera = u_cameraPos - v_worldPos;
	vec3 view = normalize(toCamera);
	if(dot(geometric, view) < 0.0) {
		geometric = -geometric; // the polygon is seen from behind
		normal = -normal;
	}
	vec3 dir = reflect(-view, normal);
	if(dot(dir, geometric) < 0.02) {
		dir = normalize(dir - geometric * (dot(dir, geometric) - 0.02)); // keep it off the surface
	}

	// Fresnel, lifted head-on so that a glossy floor visibly mirrors (a wet look rather
	// than physically exact)
	float facing = max(dot(normal, view), 0.0);
	float fresnel = pow(1.0 - facing, 4.0);
	float weight = mix(mix(MinReflection, 1.0, fresnel), 1.0, u_material.z * 0.5) * gloss * MaxReflection * u_strength;
	if(weight <= 0.005) {
		discard;
	}

	// Trace
	vec3 origin = v_worldPos + geometric * 1.0;
	RtHit hit;
	if(!rtTrace(origin, dir, MaxDistance, false, false, hit)) {
		discard;
	}
	vec3 point = origin + dir * hit.t;

	// On screen and not hidden: take the scene colour there (characters, particles included)
	vec3 reflected;
	vec4 clip = u_proj * (u_view * vec4(point, 1.0));
	vec3 viewPoint = (u_view * vec4(point, 1.0)).xyz;
	bool onScreen = false;
	if(clip.w > 0.0) {
		vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
		if(uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
			float sceneZ = linearDepth(texture(u_depth, uv).r);
			if(abs(sceneZ - viewPoint.z) < max(viewPoint.z * SceneTolerance, 8.0)) {
				reflected = texture(u_scene, uv).rgb;
				onScreen = true;
			}
		}
	}
	if(!onScreen) {
		float blur = (1.0 - gloss) * RoughnessBlur + clamp(log2(hit.t / 512.0), 0.0, 3.0);
		reflected = shadeHit(hit, point, dir, blur);
		if(u_fogEnabled != 0) {
			// The light travels from the hit to the surface and on to the camera
			float travelled = length(toCamera) + hit.t;
			float fog = clamp((u_fogRange.y - travelled) / (u_fogRange.y - u_fogRange.x), 0.0, 1.0);
			reflected = mix(u_fogColor, reflected, fog);
		}
	}

	// Metals tint their reflections
	vec3 albedo = texture(u_texture0, v_uv).rgb;
	reflected *= mix(vec3(1.0), albedo * 1.5, u_material.z);

	if(u_fogEnabled != 0) {
		float fog = clamp((u_fogRange.y - v_viewPos.z) / (u_fogRange.y - u_fogRange.x), 0.0, 1.0);
		weight *= fog;
	}

	fragColor = vec4(reflected, weight);
}
)glsl";

